-- Frozen evidence is validated independently at insertion, sealing and opening.
-- Predicates are pure Rust functions; JSON true/false are never SQL 1/0 types.
CREATE VIEW banking_evidence_invalid AS
SELECT id,'deposit' kind FROM banking_deposit WHERE fb_banking_uuid(actor_id)<>1 OR fb_banking_payload('deposit',data)<>1 OR fb_banking_date(date)<>1 OR fb_banking_uuid(id)<>1 OR fb_banking_uuid(company_id)<>1 OR fb_banking_uuid(identity_id)<>1 OR fb_banking_uuid(bank_id)<>1 OR fb_banking_uuid(journal_id)<>1 OR fb_banking_money(json_quote(json_extract(data,'$.amount'))) IS NOT amount OR json_extract(data,'$.id') IS NOT id OR json_extract(data,'$.company_id') IS NOT company_id OR json_extract(data,'$.identity_id') IS NOT identity_id OR json_extract(data,'$.bank_id') IS NOT bank_id OR json_extract(data,'$.journal_id') IS NOT journal_id OR json_extract(data,'$.date') IS NOT date
UNION ALL SELECT id,'reversal' kind FROM banking_depositreversal WHERE fb_banking_uuid(actor_id)<>1 OR fb_banking_payload('reversal',data)<>1 OR fb_banking_date(date)<>1 OR fb_banking_uuid(id)<>1 OR fb_banking_uuid(deposit_id)<>1 OR fb_banking_uuid(journal_id)<>1 OR json_extract(data,'$.id') IS NOT id OR json_extract(data,'$.deposit_id') IS NOT deposit_id OR json_extract(data,'$.journal_id') IS NOT journal_id OR json_extract(data,'$.date') IS NOT date
UNION ALL SELECT id,'reconciliation' kind FROM banking_reconciliation WHERE fb_banking_uuid(started_by_id)<>1 OR fb_banking_payload('reconciliation',data)<>1 OR fb_banking_date(statement_date)<>1 OR fb_banking_uuid(id)<>1 OR fb_banking_uuid(company_id)<>1 OR fb_banking_uuid(account_id)<>1 OR fb_banking_uuid(request_key)<>1 OR fb_banking_money(json_quote(json_extract(data,'$.ending_balance'))) IS NOT ending_balance OR json_extract(data,'$.id') IS NOT id OR json_extract(data,'$.company_id') IS NOT company_id OR json_extract(data,'$.account_id') IS NOT account_id OR json_extract(data,'$.request_key') IS NOT request_key OR json_extract(data,'$.statement_date') IS NOT statement_date OR json_extract(data,'$.status') IS NOT status OR json_extract(data,'$.creation_digest') IS NOT creation_digest OR json_extract(data,'$.revision') IS NOT revision OR json_extract(data,'$.hide_later') IS NOT hide_later
UNION ALL SELECT id,'banking_depositline' FROM banking_depositline WHERE fb_banking_uuid(id)<>1 OR fb_banking_uuid(deposit_id)<>1 OR fb_banking_uuid(receipt_id)<>1 OR fb_banking_uuid(undeposited_id)<>1
UNION ALL SELECT id,'banking_banklinestatus' FROM banking_banklinestatus WHERE fb_banking_uuid(id)<>1 OR fb_banking_uuid(company_id)<>1 OR fb_banking_uuid(journal_line_id)<>1 OR fb_banking_uuid(account_id)<>1 OR fb_banking_uuid(changed_by_id)<>1 OR (reconciliation_id IS NOT NULL AND fb_banking_uuid(reconciliation_id)<>1)
UNION ALL SELECT id,'banking_reconciliationline' FROM banking_reconciliationline WHERE fb_banking_uuid(id)<>1 OR fb_banking_uuid(reconciliation_id)<>1 OR fb_banking_uuid(journal_line_id)<>1
UNION ALL SELECT reconciliation_id,'banking_reconciliationactor' FROM banking_reconciliationactor WHERE fb_banking_uuid(reconciliation_id)<>1 OR fb_banking_uuid(user_id)<>1;
CREATE TRIGGER fb_banking_deposit_evidence_insert BEFORE INSERT ON banking_deposit BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid stored payload, date or key') WHERE fb_banking_payload('deposit',NEW.data)<>1 OR fb_banking_date(NEW.date)<>1 OR fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.company_id)<>1 OR fb_banking_uuid(NEW.identity_id)<>1 OR fb_banking_uuid(NEW.bank_id)<>1 OR fb_banking_uuid(NEW.journal_id)<>1 OR fb_banking_uuid(NEW.actor_id)<>1; END;
CREATE TRIGGER fb_banking_deposit_evidence_update BEFORE UPDATE ON banking_deposit BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid stored payload, date or key') WHERE fb_banking_payload('deposit',NEW.data)<>1 OR fb_banking_date(NEW.date)<>1 OR fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.company_id)<>1 OR fb_banking_uuid(NEW.identity_id)<>1 OR fb_banking_uuid(NEW.bank_id)<>1 OR fb_banking_uuid(NEW.journal_id)<>1 OR fb_banking_uuid(NEW.actor_id)<>1; END;
CREATE TRIGGER fb_banking_reversal_evidence_insert BEFORE INSERT ON banking_depositreversal BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid stored payload, date or key') WHERE fb_banking_payload('reversal',NEW.data)<>1 OR fb_banking_date(NEW.date)<>1 OR fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.deposit_id)<>1 OR fb_banking_uuid(NEW.journal_id)<>1 OR fb_banking_uuid(NEW.actor_id)<>1; END;
CREATE TRIGGER fb_banking_reversal_evidence_update BEFORE UPDATE ON banking_depositreversal BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid stored payload, date or key') WHERE fb_banking_payload('reversal',NEW.data)<>1 OR fb_banking_date(NEW.date)<>1 OR fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.deposit_id)<>1 OR fb_banking_uuid(NEW.journal_id)<>1 OR fb_banking_uuid(NEW.actor_id)<>1; END;
CREATE TRIGGER fb_banking_reconciliation_evidence_insert BEFORE INSERT ON banking_reconciliation BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid stored payload, date or key') WHERE fb_banking_payload('reconciliation',NEW.data)<>1 OR fb_banking_date(NEW.statement_date)<>1 OR fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.company_id)<>1 OR fb_banking_uuid(NEW.account_id)<>1 OR fb_banking_uuid(NEW.request_key)<>1 OR fb_banking_uuid(NEW.started_by_id)<>1; END;
CREATE TRIGGER fb_banking_reconciliation_evidence_update BEFORE UPDATE ON banking_reconciliation BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid stored payload, date or key') WHERE fb_banking_payload('reconciliation',NEW.data)<>1 OR fb_banking_date(NEW.statement_date)<>1 OR fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.company_id)<>1 OR fb_banking_uuid(NEW.account_id)<>1 OR fb_banking_uuid(NEW.request_key)<>1 OR fb_banking_uuid(NEW.started_by_id)<>1; END;
CREATE TRIGGER fb_banking_evidence_seal BEFORE INSERT ON banking_seal BEGIN
 SELECT RAISE(ABORT,'banking_evidence: Invalid stored payload, date or key') WHERE EXISTS(
 SELECT 1 FROM banking_evidence_invalid v WHERE
 (NEW.kind='deposit' AND v.kind='deposit' AND v.id=NEW.doc_id) OR
 (NEW.kind='journal' AND ((v.kind='deposit' AND EXISTS(SELECT 1 FROM banking_deposit d WHERE d.id=v.id AND d.journal_id=NEW.doc_id)) OR (v.kind='reversal' AND EXISTS(SELECT 1 FROM banking_depositreversal z WHERE z.id=v.id AND z.journal_id=NEW.doc_id)))) OR
 (NEW.kind='reconciliation' AND v.kind='reconciliation' AND EXISTS(SELECT 1 FROM banking_reconciliation r WHERE r.id=v.id AND r.id||':'||r.revision=NEW.doc_id)));
END;
CREATE TRIGGER fb_banking_new_charge_insert BEFORE INSERT ON banking_reconciliation BEGIN
 SELECT RAISE(ABORT,'reconciliation_charge_eligibility: New charges require eligible accounts') WHERE EXISTS(
 SELECT 1 FROM (SELECT 'service' prefix,'EXPENSE' kind UNION ALL SELECT 'interest','INCOME') x
 WHERE json_extract(NEW.data,'$.'||x.prefix||'_journal_id') IS NOT NULL
 AND (NOT EXISTS(SELECT 1 FROM ledger_account b WHERE b.id=json_extract(NEW.data,'$.'||x.prefix||'_account_id') AND b.company_id=NEW.company_id AND b.active=1 AND b.postable=1 AND b.kind=x.kind AND b.id<>NEW.account_id)
 OR NOT EXISTS(SELECT 1 FROM banking_register_account a WHERE a.id=NEW.account_id AND a.company_id=NEW.company_id AND a.active=1 AND a.postable=1 AND (x.prefix<>'interest' OR a.kind IN('ASSET','EXPENSE')))));
END;
CREATE TRIGGER fb_banking_new_charge_update BEFORE UPDATE ON banking_reconciliation BEGIN
 SELECT RAISE(ABORT,'reconciliation_charge_eligibility: New charges require eligible accounts') WHERE EXISTS(
 SELECT 1 FROM (SELECT 'service' prefix,'EXPENSE' kind UNION ALL SELECT 'interest','INCOME') x
 WHERE json_extract(NEW.data,'$.'||x.prefix||'_journal_id') IS NOT NULL AND json_extract(OLD.data,'$.'||x.prefix||'_journal_id') IS NULL
 AND (NOT EXISTS(SELECT 1 FROM ledger_account b WHERE b.id=json_extract(NEW.data,'$.'||x.prefix||'_account_id') AND b.company_id=NEW.company_id AND b.active=1 AND b.postable=1 AND b.kind=x.kind AND b.id<>NEW.account_id)
 OR NOT EXISTS(SELECT 1 FROM banking_register_account a WHERE a.id=NEW.account_id AND a.company_id=NEW.company_id AND a.active=1 AND a.postable=1 AND (x.prefix<>'interest' OR a.kind IN('ASSET','EXPENSE')))));
END;
CREATE TRIGGER fb_banking_depositline_uuid_insert BEFORE INSERT ON banking_depositline BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid banking UUID') WHERE fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.deposit_id)<>1 OR fb_banking_uuid(NEW.receipt_id)<>1 OR fb_banking_uuid(NEW.undeposited_id)<>1; END;
CREATE TRIGGER fb_banking_depositline_uuid_update BEFORE UPDATE ON banking_depositline BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid banking UUID') WHERE fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.deposit_id)<>1 OR fb_banking_uuid(NEW.receipt_id)<>1 OR fb_banking_uuid(NEW.undeposited_id)<>1; END;
CREATE TRIGGER fb_banking_banklinestatus_uuid_insert BEFORE INSERT ON banking_banklinestatus BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid banking UUID') WHERE fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.company_id)<>1 OR fb_banking_uuid(NEW.journal_line_id)<>1 OR fb_banking_uuid(NEW.account_id)<>1 OR fb_banking_uuid(NEW.changed_by_id)<>1 OR (NEW.reconciliation_id IS NOT NULL AND fb_banking_uuid(NEW.reconciliation_id)<>1); END;
CREATE TRIGGER fb_banking_banklinestatus_uuid_update BEFORE UPDATE ON banking_banklinestatus BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid banking UUID') WHERE fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.company_id)<>1 OR fb_banking_uuid(NEW.journal_line_id)<>1 OR fb_banking_uuid(NEW.account_id)<>1 OR fb_banking_uuid(NEW.changed_by_id)<>1 OR (NEW.reconciliation_id IS NOT NULL AND fb_banking_uuid(NEW.reconciliation_id)<>1); END;
CREATE TRIGGER fb_banking_reconciliationline_uuid_insert BEFORE INSERT ON banking_reconciliationline BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid banking UUID') WHERE fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.reconciliation_id)<>1 OR fb_banking_uuid(NEW.journal_line_id)<>1; END;
CREATE TRIGGER fb_banking_reconciliationline_uuid_update BEFORE UPDATE ON banking_reconciliationline BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid banking UUID') WHERE fb_banking_uuid(NEW.id)<>1 OR fb_banking_uuid(NEW.reconciliation_id)<>1 OR fb_banking_uuid(NEW.journal_line_id)<>1; END;
CREATE TRIGGER fb_banking_reconciliationactor_uuid_insert BEFORE INSERT ON banking_reconciliationactor BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid banking UUID') WHERE fb_banking_uuid(NEW.reconciliation_id)<>1 OR fb_banking_uuid(NEW.user_id)<>1; END;
CREATE TRIGGER fb_banking_reconciliationactor_uuid_update BEFORE UPDATE ON banking_reconciliationactor BEGIN SELECT RAISE(ABORT,'banking_evidence: Invalid banking UUID') WHERE fb_banking_uuid(NEW.reconciliation_id)<>1 OR fb_banking_uuid(NEW.user_id)<>1; END;
